@st.cache_resource
def get_supabase():
    url = st.secrets["SUPABASE_URL"]
    key = st.secrets["SUPABASE_KEY"]
    return create_client(url, key)


def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


def current_user():
    return st.session_state.get("user", None)


def is_admin():
    u = current_user()
    return bool(u and u.get("ruolo") == "admin")


def user_label():
    u = current_user()
    return u.get("nome", "Utente non identificato") if u else "Utente non identificato"


def now_iso():
    return datetime.now().isoformat(timespec="seconds")


def norm(v):
    return "" if v is None else str(v).strip().lower()


def add_months(d: date, months: int) -> date:
    month = d.month - 1 + months
    year = d.year + month // 12
    month = month % 12 + 1
    days = [31, 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28,
            31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return date(year, month, min(d.day, days[month - 1]))



def mesi_scadenza_abbonamento_kreo(tipologia_abbonamento):
    """
    Funzione blindata per scadenza pacchetto.
    Non usa frequenza pagamento e non usa vecchie logiche.
    """
    t = str(tipologia_abbonamento or "").strip().upper()
    if t == "MENSILE" or "MENSILE" in t:
        return 1
    if t == "TRIMESTRALE" or "TRIMESTRALE" in t:
        return 3
    if t == "SEMESTRALE" or "SEMESTRALE" in t:
        return 6
    if t == "ANNUALE" or "ANNUALE" in t:
        return 12
    return None


def calcola_scadenza_abbonamento_blindata(data_inizio, tipologia_abbonamento, pacchetto):
    if "PERSONALIZZATO" in str(pacchetto or "").upper():
        return None
    mesi = mesi_scadenza_abbonamento_kreo(tipologia_abbonamento)
    if mesi is None:
        return None
    return add_months(parse_date(data_inizio, date.today()), mesi)


def label_scadenza_abbonamento_blindata(data_inizio, tipologia_abbonamento, pacchetto):
    scad = calcola_scadenza_abbonamento_blindata(data_inizio, tipologia_abbonamento, pacchetto)
    if scad is None:
        if "PERSONALIZZATO" in str(pacchetto or "").upper():
            return "Pacchetto personalizzato: nessuna scadenza automatica."
        return "Scadenza automatica non calcolabile: verifica manuale."
    return f"Scadenza automatica prevista: {format_date_it(scad)}"


def parse_date(value, default=None):
    if not value:
        return default or date.today()
    try:
        return pd.to_datetime(value).date()
    except Exception:
        return default or date.today()


def format_date_it(value):
    if value in [None, ""] or pd.isna(value):
        return ""
    try:
        return pd.to_datetime(value).strftime("%d/%m/%Y")
    except Exception:
        return str(value)


def euro(value):
    try:
        return f"€ {float(value):,.0f}".replace(",", ".")
    except Exception:
        return "€ 0"


def load_clienti():
    sb = get_supabase()
    data = sb.table("clienti").select("*").order("id", desc=True).execute().data
    df = pd.DataFrame(data)
    if df.empty:
        return df

    for col in ["importo", "importo_pagato"]:
        if col not in df.columns:
            df[col] = 0
        df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

    for col in ["numero_lezioni", "lezioni_utilizzate"]:
        if col not in df.columns:
            df[col] = 0
        df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0).astype(int)

    df["residuo"] = (df["importo"] - df["importo_pagato"]).clip(lower=0)
    df["stato_pagamento"] = df["residuo"].apply(lambda x: "PAGATO" if x <= 0 else "DA SALDARE")
    df["lezioni_residue"] = (df["numero_lezioni"] - df["lezioni_utilizzate"]).clip(lower=0)

    for c in ["data_iscrizione", "data_inizio_pacchetto", "scadenza_certificato", "scadenza_abbonamento"]:
        if c in df.columns:
            df[c + "_it"] = df[c].apply(format_date_it)

    return df


def get_cliente(cliente_id):
    """
    Lettura robusta cliente.
    Prima prova Supabase diretto; se Supabase dà timeout/read error,
    usa fallback da load_clienti() per evitare crash nel calendario.
    """
    try:
        sb = get_supabase()
        data = sb.table("clienti").select("*").eq("id", int(cliente_id)).limit(1).execute().data
        if data:
            return data[0]
    except Exception:
        pass

    # fallback locale: evita crash se Supabase/PostgREST ha un ReadError temporaneo
    try:
        df = load_clienti()
        if not df.empty and "id" in df.columns:
            tmp = df[pd.to_numeric(df["id"], errors="coerce").fillna(0).astype(int) == int(cliente_id)]
            if not tmp.empty:
                return tmp.iloc[0].to_dict()
    except Exception:
        pass

    return None

def load_history(cliente_id):
    sb = get_supabase()
    data = sb.table("cronologia").select("*").eq("cliente_id", int(cliente_id)).order("id", desc=True).execute().data
    df = pd.DataFrame(data)
    if not df.empty:
        df["data_modifica"] = df["data_modifica"].apply(lambda x: pd.to_datetime(x).strftime("%d/%m/%Y %H:%M:%S"))
    return df


def insert_history(cliente_id, campo, old, new, note=""):
    old = "" if old is None else str(old)
    new = "" if new is None else str(new)
    if old == new and campo != "CREAZIONE CLIENTE":
        return
    sb = get_supabase()
    sb.table("cronologia").insert({
        "cliente_id": int(cliente_id),
        "data_modifica": now_iso(),
        "campo": campo,
        "valore_precedente": old,
        "valore_nuovo": new,
        "note": note,
        "modified_by": user_label(),
    }).execute()


def find_existing_clienti_for_data(data, exclude_id=None):
    df = load_clienti()
    if df.empty:
        return pd.DataFrame()
    if exclude_id is not None:
        df = df[df["id"] != int(exclude_id)]

    matches = pd.Series(False, index=df.index)
    cf = norm(data.get("codice_fiscale"))
    email = norm(data.get("email"))
    cell = norm(data.get("cellulare"))
    nome = norm(data.get("nome"))
    cognome = norm(data.get("cognome"))

    if cf and "codice_fiscale" in df.columns:
        matches |= df["codice_fiscale"].fillna("").astype(str).str.strip().str.lower().eq(cf)
    if email and "email" in df.columns:
        matches |= df["email"].fillna("").astype(str).str.strip().str.lower().eq(email)
    if cell and "cellulare" in df.columns:
        matches |= df["cellulare"].fillna("").astype(str).str.strip().str.lower().eq(cell)
    if nome and cognome:
        matches |= (
            df["nome"].fillna("").astype(str).str.strip().str.lower().eq(nome)
            & df["cognome"].fillna("").astype(str).str.strip().str.lower().eq(cognome)
        )
    return df[matches]


def insert_cliente(data):
    sb = get_supabase()
    payload = data.copy()
    payload["created_at"] = now_iso()
    payload["updated_at"] = now_iso()
    result = sb.table("clienti").insert(payload).execute().data
    cliente_id = result[0]["id"]
    insert_history(cliente_id, "CREAZIONE CLIENTE", "", f"{data.get('nome','')} {data.get('cognome','')}", "Cliente inserito")
    return cliente_id


def update_cliente(cliente_id, new_data):
    old = get_cliente(cliente_id)
    if not old:
        return
    payload = new_data.copy()
    payload["updated_at"] = now_iso()

    sb = get_supabase()
    sb.table("clienti").update(payload).eq("id", int(cliente_id)).execute()

    for field, new_value in new_data.items():
        insert_history(cliente_id, field, old.get(field), new_value)


def delete_cliente(cliente_id):
    sb = get_supabase()
    sb.table("clienti").delete().eq("id", int(cliente_id)).execute()
    sb.table("cronologia").delete().eq("cliente_id", int(cliente_id)).execute()


def incrementa_lezioni(cliente_id, incremento=1):
    old = get_cliente(cliente_id)
    if not old:
        return
    old_val = int(old.get("lezioni_utilizzate") or 0)
    tot = int(old.get("numero_lezioni") or 0)
    new_val = min(old_val + incremento, tot) if tot > 0 else old_val + incremento

    sb = get_supabase()
    sb.table("clienti").update({
        "lezioni_utilizzate": new_val,
        "updated_at": now_iso(),
    }).eq("id", int(cliente_id)).execute()
    insert_history(cliente_id, "lezioni_utilizzate", old_val, new_val, "Aggiornamento rapido lezioni")


def duplicate_group_key(row):
    cf = norm(row.get("codice_fiscale"))
    email = norm(row.get("email"))
    cell = norm(row.get("cellulare"))
    nome = norm(row.get("nome"))
    cognome = norm(row.get("cognome"))
    if cf:
        return "CF|" + cf
    if email:
        return "EMAIL|" + email
    if cell:
        return "CELL|" + cell
    return "NOME|" + nome + "|" + cognome


def find_duplicates(df):
    if df.empty:
        return df
    tmp = df.copy()
    tmp["dup_key"] = tmp.apply(duplicate_group_key, axis=1)
    duplicated_keys = tmp["dup_key"].value_counts()
    duplicated_keys = duplicated_keys[duplicated_keys > 1].index.tolist()
    return tmp[tmp["dup_key"].isin(duplicated_keys)].sort_values(["dup_key", "id"], ascending=[True, False])


def elimina_duplicati_tieni_ultimo():
    df = load_clienti()
    if df.empty:
        return 0
    tmp = df.copy()
    tmp["dup_key"] = tmp.apply(duplicate_group_key, axis=1)
    ids_to_delete = []

    for _, group in tmp.groupby("dup_key"):
        if len(group) > 1:
            keep_id = int(group["id"].max())
            ids_to_delete += [int(x) for x in group["id"].tolist() if int(x) != keep_id]

    for cid in ids_to_delete:
        delete_cliente(cid)
    return len(ids_to_delete)







def generate_client_password(length=8):
    alphabet = string.ascii_letters + string.digits
    return "".join(secrets.choice(alphabet) for _ in range(length))


def get_login_cliente_by_cliente_id(cliente_id):
    sb = get_supabase()
    data = sb.table("login_clienti").select("*").eq("cliente_id", int(cliente_id)).limit(1).execute().data
    return data[0] if data else None


def create_or_reset_cliente_login(cliente_id):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato.", None, None

    nome = norm(cliente.get("nome", "")).replace(" ", "")
    cognome = norm(cliente.get("cognome", "")).replace(" ", "")
    base_username = f"{nome}.{cognome}".replace("'", "").replace("à","a").replace("è","e").replace("é","e").replace("ì","i").replace("ò","o").replace("ù","u")
    if not base_username or base_username == ".":
        base_username = f"cliente{cliente_id}"
    username = base_username

    sb = get_supabase()

    existing_same_username = sb.table("login_clienti").select("*").eq("username", username).execute().data
    if existing_same_username:
        # Se username già usato da altro cliente, aggiunge ID cliente
        username = f"{base_username}{cliente_id}"

    password = generate_client_password()
    password_hash = hash_password(password)

    existing = get_login_cliente_by_cliente_id(cliente_id)
    if existing:
        sb.table("login_clienti").update({
            "username": username,
            "password_hash": password_hash,
            "attivo": True,
            "created_at": now_iso(),
        }).eq("cliente_id", int(cliente_id)).execute()
        action = "Credenziali cliente resettate"
    else:
        sb.table("login_clienti").insert({
            "cliente_id": int(cliente_id),
            "username": username,
            "password_hash": password_hash,
            "attivo": True,
            "created_at": now_iso(),
        }).execute()
        action = "Credenziali cliente create"

    insert_history(cliente_id, "area cliente", "", action, f"{action} da {user_label()} - username: {username}")
    return True, action, username, password


def get_cliente_by_login(username, password):
    sb = get_supabase()
    data = (
        sb.table("login_clienti")
        .select("*")
        .eq("username", username.strip().lower())
        .eq("attivo", True)
        .limit(1)
        .execute()
        .data
    )
    if not data:
        return None, "Cliente non trovato o accesso non attivo."

    login = data[0]
    if login.get("password_hash") != hash_password(password):
        return None, "Password errata."

    cliente = get_cliente(int(login.get("cliente_id")))
    if not cliente:
        return None, "Scheda cliente non trovata."

    return cliente, None



