def render_weekly_planner(selected_week):
    st.subheader("Planner settimanale disponibilità")
    st.caption("Versione ottimizzata: carica gli slot una sola volta e disegna la settimana più velocemente.")

    giorni = week_dates_from_monday(selected_week)
    fasce = generate_time_slots_for_day()

    week_start = min(giorni)
    week_end = max(giorni)

    # Caricamento unico slot e lezioni
    try:
        slots_all = load_disponibilita()
    except Exception:
        slots_all = pd.DataFrame()

    try:
        lez_all = load_lezioni()
    except Exception:
        lez_all = pd.DataFrame()

    if not slots_all.empty:
        slots_all["data_dt"] = pd.to_datetime(slots_all["data_slot"], errors="coerce")
        slots_week = slots_all[
            (slots_all["data_dt"] >= pd.Timestamp(week_start)) &
            (slots_all["data_dt"] <= pd.Timestamp(week_end)) &
            (slots_all["attivo"] == True)
        ].copy()
    else:
        slots_week = pd.DataFrame()

    if not lez_all.empty and "slot_id" in lez_all.columns:
        lez_valid = lez_all[~lez_all["stato"].isin(["ANNULLATO"])].copy()
        occ_by_slot = lez_valid.groupby("slot_id").size().to_dict()
    else:
        occ_by_slot = {}

    def cell_fast_html(data_slot, ora_inizio):
        if slots_week.empty:
            return '<div style="font-size:12px;opacity:.45;text-align:center;padding-top:18px;">Libero</div>'

        sub = slots_week[
            (slots_week["data_slot"].astype(str) == str(data_slot)) &
            (slots_week["ora_inizio"].astype(str).str[:5] == str(ora_inizio)[:5])
        ]

        if sub.empty:
            return '<div style="font-size:12px;opacity:.45;text-align:center;padding-top:18px;">Libero</div>'

        parts = []
        for _, s in sub.iterrows():
            sid = int(s["id"])
            occ = int(occ_by_slot.get(sid, 0))
            maxp = int(s.get("max_posti") or 1)
            tipo = s.get("tipo_slot", "")
            if tipo == "COACHING IN SEDE":
                color = "#dbeafe"; border = "#2563eb"; label = "Coaching"
            elif tipo == "ONE TO ONE":
                color = "#ecfdf5"; border = "#10b981"; label = "Luxury"
            elif tipo == "TWO TO ONE":
                color = "#fff7ed"; border = "#f97316"; label = "Gold"
            elif tipo == "THREE TO ONE":
                color = "#f5f3ff"; border = "#7c3aed"; label = "VIP"
            else:
                color = "#f8fafc"; border = "#64748b"; label = tipo

            parts.append(
                f'<div style="background:{color};border-left:4px solid {border};padding:5px 7px;border-radius:9px;margin:3px 0;font-size:11px;font-weight:800;">{label}<br>{occ}/{maxp}</div>'
            )
        return "".join(parts)

    st.markdown("""
    <style>
    .planner-wrap {
        max-height: 620px;
        overflow: auto;
        border: 1px solid rgba(212,175,55,.25);
        border-radius: 16px;
        background: rgba(255,255,255,.58);
        padding: 8px;
    }
    .planner-table {
        width:100%;
        border-collapse:separate;
        border-spacing:5px;
        table-layout:fixed;
    }
    .planner-table th {
        background:#111;
        color:white!important;
        padding:9px;
        border-radius:10px;
        font-size:12px;
        text-align:center;
        position: sticky;
        top: 0;
        z-index: 2;
    }
    .planner-time {
        background:#f8f4e8;
        border:1px solid #d4af37;
        font-weight:900;
        border-radius:10px;
        padding:7px;
        text-align:center;
        font-size:11px;
        width:70px;
        position: sticky;
        left: 0;
        z-index: 1;
    }
    .planner-cell {
        background:white;
        border:1px solid rgba(212,175,55,.35);
        border-radius:12px;
        min-height:68px;
        padding:6px;
        box-shadow:0 2px 8px rgba(0,0,0,.035);
        vertical-align:top;
    }
    </style>
    """, unsafe_allow_html=True)

    html = '<div class="planner-wrap"><table class="planner-table"><tr><th>Ora</th>'
    for g in giorni:
        html += f'<th>{g.strftime("%a")}<br>{g.strftime("%d/%m")}</th>'
    html += '</tr>'

    for start, end in fasce:
        html += f'<tr><td class="planner-time">{start}<br>{end}</td>'
        for g in giorni:
            html += f'<td class="planner-cell">{cell_fast_html(g, start)}</td>'
        html += '</tr>'

    html += '</table></div>'
    st.markdown(html, unsafe_allow_html=True)

    st.markdown("---")
    st.subheader("Crea slot selezionato")

    c1, c2, c3 = st.columns(3)
    giorno_labels = [f"{g.strftime('%d/%m/%Y')} - {g.strftime('%A')}" for g in giorni]
    fascia_labels = [f"{start} - {end}" for start, end in fasce]

    with c1:
        giorno_label = st.selectbox("Giorno", giorno_labels, key="planner_giorno")
        giorno_sel = giorni[giorno_labels.index(giorno_label)]

    with c2:
        fascia_label = st.selectbox("Orario", fascia_labels, key="planner_orario")
        start_sel, end_sel = [x.strip() for x in fascia_label.split("-")]

    with c3:
        tipo_sel = st.selectbox(
            "Tipologia slot",
            ["ONE TO ONE", "TWO TO ONE", "THREE TO ONE", "COACHING IN SEDE"],
            key="planner_tipo"
        )

    s = get_kreo_settings()
    if tipo_sel == "COACHING IN SEDE":
        st.info("Coaching in sede: libero utilizzo attrezzi. Non occupa Enzo/PT e può coesistere con altri slot.")
    elif tipo_sel == "ONE TO ONE":
        st.info(f"Luxury / One to One: trainer {s['trainer_default']} · posti {s['max_posti_luxury']}")
    elif tipo_sel == "TWO TO ONE":
        st.info(f"Gold / Two to One: trainer {s['trainer_default']} · posti {s['max_posti_gold']}")
    elif tipo_sel == "THREE TO ONE":
        st.info(f"VIP / Three to One: trainer {s['trainer_default']} · posti {s['max_posti_vip']}")

    if st.button("➕ Crea slot selezionato"):
        ok, msg = create_slot_from_planner(giorno_sel, start_sel, end_sel, tipo_sel)
        if ok:
            st.success("Slot creato correttamente.")
            st.rerun()
        else:
            st.error(msg)

    with st.expander("Elimina slot"):
        if slots_week.empty:
            st.info("Nessuno slot disponibile in questa settimana.")
        else:
            slots_del = slots_week.sort_values(["data_slot", "ora_inizio"], ascending=[True, True]).copy()
            slots_del["label"] = (
                slots_del["id"].astype(str) + " - " +
                slots_del["data_slot"].apply(format_date_it).astype(str) + " " +
                slots_del["ora_inizio"].astype(str) + "-" + slots_del["ora_fine"].astype(str) + " / " +
                slots_del["tipo_slot"].astype(str) + " / " +
                slots_del["trainer"].astype(str)
            )
            selected = st.selectbox("Slot da eliminare", slots_del["label"].tolist())
            slot_id = int(selected.split(" - ")[0])
            if st.button("🗑 Elimina slot selezionato"):
                ok, msg = delete_slot_disponibilita(slot_id)
                if ok:
                    st.success(msg)
                    st.rerun()
                else:
                    st.error(msg)



def load_disponibilita():
    sb = get_supabase()
    data = sb.table("disponibilita_calendario").select("*").order("data_slot", desc=False).execute().data
    df = pd.DataFrame(data)
    if df.empty:
        return df
    df["data_slot_it"] = df["data_slot"].apply(format_date_it)
    return df


def create_slot_disponibilita(data_slot, ora_inizio, ora_fine, trainer, tipo_slot, max_posti, note):
    sb = get_supabase()
    sb.table("disponibilita_calendario").insert({
        "data_slot": str(data_slot),
        "ora_inizio": str(ora_inizio),
        "ora_fine": str(ora_fine),
        "trainer": trainer,
        "tipo_slot": tipo_slot,
        "max_posti": int(max_posti),
        "note": note,
        "attivo": True,
        "created_by": user_label(),
        "created_at": now_iso(),
    }).execute()
    return True, "Disponibilità creata correttamente."


def delete_slot_disponibilita(slot_id):
    if not is_admin():
        return False, "Operazione riservata all’amministratore."
    sb = get_supabase()
    sb.table("disponibilita_calendario").delete().eq("id", int(slot_id)).execute()
    return True, "Slot eliminato."


def prenotazioni_per_slot(slot_id):
    try:
        lez_df = load_lezioni()
    except Exception:
        return pd.DataFrame()
    if lez_df.empty or "slot_id" not in lez_df.columns:
        return pd.DataFrame()
    return lez_df[
        (lez_df["slot_id"].fillna(0).astype(int) == int(slot_id)) &
        (~lez_df["stato"].isin(["ANNULLATO"]))
    ]


def posti_occupati_slot(slot_id):
    pren = prenotazioni_per_slot(slot_id)
    return 0 if pren.empty else len(pren)


def slot_disponibili_per_cliente(cliente_id):
    slots = load_disponibilita()
    if slots.empty:
        return slots
    today = pd.Timestamp(date.today())
    slots["data_dt"] = pd.to_datetime(slots["data_slot"], errors="coerce")
    slots = slots[(slots["attivo"] == True) & (slots["data_dt"] >= today)].copy()

    if slots.empty:
        return slots

    posti_occupati = []
    stato_slot = []
    for _, s in slots.iterrows():
        occ = posti_occupati_slot(int(s["id"]))
        max_p = int(s.get("max_posti") or 1)
        posti_occupati.append(occ)
        stato_slot.append("LIBERO" if occ < max_p else "PIENO")

    slots["posti_occupati"] = posti_occupati
    slots["posti_liberi"] = slots["max_posti"].astype(int) - slots["posti_occupati"]
    slots["stato_slot"] = stato_slot
    return slots


def richiesta_prenotazione_cliente(cliente_id, slot_id, note_cliente=""):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato."

    slots = load_disponibilita()
    if slots.empty:
        return False, "Nessuna disponibilità trovata."
    slot = slots[slots["id"].astype(int) == int(slot_id)]
    if slot.empty:
        return False, "Slot non trovato."
    slot = slot.iloc[0].to_dict()

    if posti_occupati_slot(slot_id) >= int(slot.get("max_posti") or 1):
        return False, "Slot non più disponibile."

    # Evita doppia prenotazione dello stesso cliente sullo stesso slot
    pren = prenotazioni_per_slot(slot_id)
    if not pren.empty and int(cliente_id) in pren["cliente_id"].astype(int).tolist():
        return False, "Hai già una prenotazione/richiesta su questo slot."

    ok_pag, msg_pag = cliente_in_regola_pagamenti(cliente)
    if not ok_pag:
        return False, msg_pag

    ok_week, msg_week = cliente_puo_prenotare_settimana(cliente_id, parse_date(slot.get("data_slot"), date.today()))
    if not ok_week:
        return False, msg_week

    sb = get_supabase()
    sb.table("lezioni").insert({
        "cliente_id": int(cliente_id),
        "slot_id": int(slot_id),
        "data_lezione": str(slot.get("data_slot")),
        "ora_inizio": str(slot.get("ora_inizio")),
        "ora_fine": str(slot.get("ora_fine")),
        "trainer": slot.get("trainer"),
        "stato": "RICHIESTA CLIENTE",
        "note": note_cliente,
        "creata_da": f"Cliente: {cliente.get('nome','')} {cliente.get('cognome','')}",
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }).execute()

    insert_history(
        cliente_id,
        "richiesta prenotazione cliente",
        "",
        f"{format_date_it(slot.get('data_slot'))} {slot.get('ora_inizio')}-{slot.get('ora_fine')}",
        f"Richiesta prenotazione da area cliente | Trainer: {slot.get('trainer')}"
    )
    return True, "Richiesta prenotazione inviata allo staff."



def load_lezioni():
    sb = get_supabase()
    data = sb.table("lezioni").select("*").order("data_lezione", desc=False).execute().data
    df = pd.DataFrame(data)
    if df.empty:
        return df
    df["data_lezione_it"] = df["data_lezione"].apply(format_date_it)
    return df


def insert_lezione(cliente_id, data_lezione, ora_inizio, ora_fine, trainer, stato, note):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato o Supabase temporaneamente non raggiungibile. Riprova tra pochi secondi."

    sb = get_supabase()
    sb.table("lezioni").insert({
        "cliente_id": int(cliente_id),
        "data_lezione": str(data_lezione),
        "ora_inizio": str(ora_inizio),
        "ora_fine": str(ora_fine),
        "trainer": trainer,
        "stato": stato,
        "note": note,
        "creata_da": user_label(),
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }).execute()

    insert_history(
        cliente_id,
        "prenotazione lezione",
        "",
        f"{format_date_it(data_lezione)} {ora_inizio}-{ora_fine}",
        f"Lezione creata da {user_label()} | Trainer: {trainer} | Stato: {stato}"
    )
    return True, "Lezione/prenotazione creata correttamente."



def storico_presenze_cliente(cliente_id):
    """
    Storico presenze del singolo cliente.
    Usa la tabella lezioni filtrata per cliente e stato PRESENTE.
    """
    try:
        lez = load_lezioni()
        if lez.empty:
            return pd.DataFrame()
        tmp = lez.copy()
        tmp["cliente_id_num"] = pd.to_numeric(tmp["cliente_id"], errors="coerce").fillna(0).astype(int)
        tmp["stato_norm"] = tmp["stato"].astype(str).str.upper()
        tmp = tmp[
            (tmp["cliente_id_num"] == int(cliente_id)) &
            (tmp["stato_norm"] == "PRESENTE")
        ].sort_values(["data_lezione", "ora_inizio"], ascending=[False, False])
        return tmp
    except Exception:
        return pd.DataFrame()



def aggiorna_contatori_dopo_presenza_lezione(cliente_id):
    """
    Dopo una presenza di tipo LEZIONE:
    - ricalcola totale/usate/residue
    - aggiorna anagrafica cliente
    Funziona per tutti i pacchetti.
    """
    try:
        totale, usate, residue = contatori_cumulativi_cliente(int(cliente_id))
        if "safe_update_cliente_contatori" in globals():
            safe_update_cliente_contatori(int(cliente_id), totale, usate, residue)
        else:
            sb = get_supabase()
            sb.table("clienti").update({
                "numero_lezioni": int(totale),
                "lezioni_utilizzate": int(usate),
                "lezioni_residue": int(residue),
                "updated_at": now_iso(),
            }).eq("id", int(cliente_id)).execute()
        return True
    except Exception:
        return False


def registra_presenza_cliente(cliente_id, data_presenza, ora_inizio, ora_fine, tipo_attivita, trainer, note=""):
    """
    Inserisce una presenza manuale cliente.
    Salva su lezioni con stato PRESENTE, così aggiorna anche contatori e calendario.
    """
    cliente = get_cliente(int(cliente_id))
    if not cliente:
        return False, "Cliente non trovato."

    note_finale = f"Presenza manuale | Tipo attività: {tipo_attivita}"
    if note:
        note_finale += f" | Note: {note}"

    try:
        ok, msg = insert_lezione(
            cliente_id=int(cliente_id),
            data_lezione=data_presenza,
            ora_inizio=str(ora_inizio),
            ora_fine=str(ora_fine),
            trainer=trainer,
            stato="PRESENTE",
            note=note_finale,
        )
        if ok:
            # Se è una LEZIONE, scala automaticamente dalle lezioni residue
            # perché viene salvata come stato PRESENTE nella tabella lezioni.
            if str(tipo_attivita).upper() == "LEZIONE":
                aggiorna_contatori_dopo_presenza_lezione(int(cliente_id))

            insert_history(
                int(cliente_id),
                "presenza manuale",
                "",
                f"{format_date_it(data_presenza)} {ora_inizio}-{ora_fine}",
                f"{tipo_attivita} | Trainer: {trainer} | {note}"
            )
        return ok, "Presenza registrata correttamente. Lezione scalata dalle residue." if ok and str(tipo_attivita).upper() == "LEZIONE" else ("Presenza registrata correttamente." if ok else msg)
    except Exception as e:
        return False, f"Errore registrazione presenza: {e}"



def elimina_presenza_lezione_cliente(lezione_id):
    """
    Elimina una presenza/lezione del cliente dalla tabella lezioni
    e ricalcola i contatori del cliente.
    """
    try:
        sb = get_supabase()
        data = sb.table("lezioni").select("*").eq("id", int(lezione_id)).limit(1).execute().data
        if not data:
            return False, "Presenza/lezione non trovata."

        lezione = data[0]
        cliente_id = int(lezione.get("cliente_id"))

        sb.table("lezioni").delete().eq("id", int(lezione_id)).execute()

        try:
            totale, usate, residue = contatori_cumulativi_cliente(cliente_id)
            if "safe_update_cliente_contatori" in globals():
                safe_update_cliente_contatori(cliente_id, totale, usate, residue)
            else:
                sb.table("clienti").update({
                    "numero_lezioni": int(totale),
                    "lezioni_utilizzate": int(usate),
                    "lezioni_residue": int(residue),
                    "updated_at": now_iso(),
                }).eq("id", cliente_id).execute()
        except Exception:
            pass

        insert_history(
            cliente_id,
            "eliminazione presenza/lezione",
            f"{lezione.get('data_lezione')} {lezione.get('ora_inizio')}-{lezione.get('ora_fine')}",
            "",
            f"Eliminata da {user_label()} | Stato: {lezione.get('stato')} | Note: {lezione.get('note','')}"
        )

        return True, "Presenza/lezione eliminata e contatori aggiornati."
    except Exception as e:
        return False, f"Errore eliminazione presenza: {e}"


