def update_stato_lezione(lezione_id, nuovo_stato):
    sb = get_supabase()
    data = sb.table("lezioni").select("*").eq("id", int(lezione_id)).limit(1).execute().data
    if not data:
        return False, "Lezione non trovata."

    lezione = data[0]
    old_stato = lezione.get("stato", "")
    cliente_id = int(lezione.get("cliente_id"))

    sb.table("lezioni").update({
        "stato": nuovo_stato,
        "updated_at": now_iso(),
        "aggiornata_da": user_label(),
    }).eq("id", int(lezione_id)).execute()

    if nuovo_stato == "PRESENTE" and old_stato != "PRESENTE":
        cliente = get_cliente(cliente_id)
        old_val = int(cliente.get("lezioni_utilizzate") or 0)
        tot = int(cliente.get("numero_lezioni") or 0)
        new_val = min(old_val + 1, tot) if tot > 0 else old_val + 1
        sb.table("clienti").update({
            "lezioni_utilizzate": new_val,
            "updated_at": now_iso(),
        }).eq("id", cliente_id).execute()
        insert_history(cliente_id, "lezioni_utilizzate", old_val, new_val, f"Presenza confermata da calendario da {user_label()}")

    insert_history(
        cliente_id,
        "stato lezione",
        old_stato,
        nuovo_stato,
        f"Lezione ID {lezione_id} aggiornata da {user_label()}"
    )
    return True, "Stato lezione aggiornato."


def delete_lezione(lezione_id):
    if not is_admin():
        return False, "Operazione riservata all’amministratore."
    sb = get_supabase()
    data = sb.table("lezioni").select("*").eq("id", int(lezione_id)).limit(1).execute().data
    if not data:
        return False, "Lezione non trovata."
    lezione = data[0]
    cliente_id = int(lezione.get("cliente_id"))
    sb.table("lezioni").delete().eq("id", int(lezione_id)).execute()
    insert_history(cliente_id, "eliminazione lezione", f"Lezione ID {lezione_id}", "", f"Eliminata da {user_label()}")
    return True, "Lezione eliminata."


def build_staff_dashboard(df_clienti):
    sb = get_supabase()

    cron = pd.DataFrame(sb.table("cronologia").select("*").execute().data)
    try:
        pag = pd.DataFrame(sb.table("pagamenti").select("*").execute().data)
    except Exception:
        pag = pd.DataFrame()
    try:
        lez = pd.DataFrame(sb.table("lezioni").select("*").execute().data)
    except Exception:
        lez = pd.DataFrame()

    rows = []
    staff_names = set()

    if not cron.empty and "modified_by" in cron.columns:
        staff_names.update(cron["modified_by"].dropna().astype(str).tolist())
    if not pag.empty and "registrato_da" in pag.columns:
        staff_names.update(pag["registrato_da"].dropna().astype(str).tolist())
    if not lez.empty and "creata_da" in lez.columns:
        staff_names.update(lez["creata_da"].dropna().astype(str).tolist())
    if not lez.empty and "aggiornata_da" in lez.columns:
        staff_names.update(lez["aggiornata_da"].dropna().astype(str).tolist())

    for nome in sorted([x for x in staff_names if x.strip()]):
        clienti_registrati = 0
        rinnovi = 0
        notifiche = 0
        incassi = 0
        lezioni_create = 0
        presenze = 0

        if not cron.empty and "modified_by" in cron.columns:
            c = cron[cron["modified_by"] == nome]
            if "campo" in c.columns:
                clienti_registrati = int((c["campo"] == "CREAZIONE CLIENTE").sum())
                rinnovi = int(c["campo"].astype(str).str.contains("pagamento|AGGIORNAMENTO DA NUOVA ISCRIZIONE", case=False, na=False).sum())
                notifiche = int(c["campo"].astype(str).str.contains("notifica|alert|whatsapp", case=False, na=False).sum())

        if not pag.empty and "registrato_da" in pag.columns:
            p = pag[pag["registrato_da"] == nome]
            if not p.empty and "importo" in p.columns:
                incassi = float(pd.to_numeric(p["importo"], errors="coerce").fillna(0).sum())

        if not lez.empty and "creata_da" in lez.columns:
            l = lez[lez["creata_da"] == nome]
            lezioni_create = int(len(l))

        if not lez.empty and "aggiornata_da" in lez.columns and "stato" in lez.columns:
            pr = lez[(lez["aggiornata_da"] == nome) & (lez["stato"] == "PRESENTE")]
            presenze = int(len(pr))

        rows.append({
            "Utente": nome,
            "Nuovi clienti registrati": clienti_registrati,
            "Rinnovi / aggiornamenti": rinnovi,
            "Notifiche tracciate": notifiche,
            "Incassi registrati": euro(incassi),
            "Lezioni create": lezioni_create,
            "Presenze confermate": presenze,
        })

    return pd.DataFrame(rows)




DOCUMENTI_BUCKET_PRIVATO = "documenti_privati"
ASSETS_BUCKET_PUBBLICO = "assets_pubblici"


def signed_document_url(storage_path, expires_in=300):
    """
    Crea link temporaneo per documenti privati.
    Durata default: 5 minuti.
    """
    if not storage_path:
        return ""
    try:
        sb = get_supabase()
        res = sb.storage.from_(DOCUMENTI_BUCKET_PRIVATO).create_signed_url(storage_path, expires_in)
        if isinstance(res, dict):
            return res.get("signedURL") or res.get("signedUrl") or res.get("url") or ""
        return str(res)
    except Exception:
        return ""


def document_url_for_display(row, expires_in=300):
    """
    Compatibilità:
    - nuovi documenti: storage_path su bucket privato
    - vecchi documenti: public_url su vecchio bucket documenti
    """
    storage_path = row.get("storage_path") if hasattr(row, "get") else ""
    url = signed_document_url(storage_path, expires_in)
    if url:
        return url
    return row.get("public_url", "") if hasattr(row, "get") else ""


