def logo_path_for_pdf():
    # Cerca il logo tra i file più probabili nel repo/app.
    # Se non lo trova, la ricevuta viene generata comunque senza logo.
    candidates = [
        "logo.png", "kreo_logo.png", "logo_kreo.png",
        "assets/logo.png", "assets/kreo_logo.png", "assets/logo_kreo.png",
        "/mount/src/kreoyourplace/logo.png",
        "/mount/src/kreoyourplace/assets/logo.png",
    ]
    for c in candidates:
        try:
            p = Path(c)
            if p.exists():
                return str(p)
        except Exception:
            continue
    return None


def make_ricevuta_pdf(cliente, pagamento):
    buffer = BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=1.6 * cm,
        leftMargin=1.6 * cm,
        topMargin=1.4 * cm,
        bottomMargin=1.4 * cm,
    )

    info = genesis_info()
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="KreoTitle",
        parent=styles["Title"],
        alignment=TA_CENTER,
        fontSize=22,
        leading=26,
        textColor=colors.HexColor("#111111"),
        spaceAfter=10,
    ))
    styles.add(ParagraphStyle(
        name="KreoSub",
        parent=styles["Normal"],
        alignment=TA_CENTER,
        fontSize=10,
        leading=13,
        textColor=colors.HexColor("#555555"),
    ))
    styles.add(ParagraphStyle(
        name="KreoSection",
        parent=styles["Heading2"],
        fontSize=13,
        leading=16,
        textColor=colors.HexColor("#111111"),
        spaceBefore=12,
        spaceAfter=8,
    ))
    styles.add(ParagraphStyle(
        name="KreoNormal",
        parent=styles["Normal"],
        fontSize=10,
        leading=13,
        textColor=colors.HexColor("#222222"),
    ))

    story = []

    logo_path = logo_path_for_pdf()
