    try:
        created_at_fmt = pd.to_datetime(created_at).strftime("%d/%m/%Y %H:%M") if created_at else ""
    except Exception:
        created_at_fmt = created_at

    cliente_nome = f"{cliente.get('nome','')} {cliente.get('cognome','')}".strip()
    cliente_cf = cliente.get("codice_fiscale", "")
    cliente_tel = cliente.get("cellulare", "")
    cliente_email = cliente.get("email", "")

    story.append(Paragraph("Dati ricevuta", styles["KreoSection"]))

    rows = [
        ["Ricevuta n.", str(pagamento_id)],
        ["Data pagamento", data_pagamento],
        ["Registrata il", created_at_fmt],
        ["Metodo pagamento", pagamento.get("metodo_pagamento", "")],
        ["Importo incassato", euro(float(pagamento.get("importo") or 0))],
        ["Rata", pagamento.get("rata_label", "") or "Acconto / pagamento non associato a rata"],
        ["Registrato da", pagamento.get("registrato_da", "")],
    ]

    tbl = Table(rows, colWidths=[5.2 * cm, 10.2 * cm])
    tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F7F2E7")),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.HexColor("#111111")),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#D4AF37")),
        ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
        ("FONTNAME", (1, 0), (1, -1), "Helvetica"),
        ("FONTSIZE", (0, 0), (-1, -1), 9.5),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 7),
    ]))
    story.append(tbl)

    story.append(Spacer(1, 14))
    story.append(Paragraph("Dati cliente", styles["KreoSection"]))

    rows_cliente = [
        ["Cliente", cliente_nome],
        ["Codice fiscale", cliente_cf],
        ["Cellulare", cliente_tel],
        ["Email", cliente_email],
        ["Pacchetto", cliente.get("pacchetto", "")],
        ["Tipologia abbonamento", cliente.get("tipologia_abbonamento", "ANNUALE")],
        ["Tipologia pagamento", cliente.get("tipologia_pagamento", "")],
    ]

    tbl2 = Table(rows_cliente, colWidths=[5.2 * cm, 10.2 * cm])
    tbl2.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F7F2E7")),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#D4AF37")),
        ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
        ("FONTNAME", (1, 0), (1, -1), "Helvetica"),
        ("FONTSIZE", (0, 0), (-1, -1), 9.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
        ("TOPPADDING", (0, 0), (-1, -1), 7),
    ]))
    story.append(tbl2)

    note = pagamento.get("note", "")
    if note:
        story.append(Spacer(1, 12))
        story.append(Paragraph("Note", styles["KreoSection"]))
        story.append(Paragraph(str(note), styles["KreoNormal"]))

    story.append(Spacer(1, 24))

    footer = """
    Il presente documento attesta la registrazione interna del pagamento ricevuto.
    Documento generato automaticamente dal gestionale KREO.
    """
    story.append(Paragraph(footer, styles["KreoSub"]))

    story.append(Spacer(1, 30))
    sign_tbl = Table(
        [["Firma operatore", "Firma cliente"], ["", ""]],
        colWidths=[7.5 * cm, 7.5 * cm],
        rowHeights=[0.7 * cm, 1.3 * cm],
    )
    sign_tbl.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("LINEABOVE", (0, 1), (0, 1), 0.6, colors.HexColor("#111111")),
        ("LINEABOVE", (1, 1), (1, 1), 0.6, colors.HexColor("#111111")),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.HexColor("#333333")),
    ]))
    story.append(sign_tbl)

    doc.build(story)
    pdf = buffer.getvalue()
    buffer.close()
    return pdf


