def render_stampa_ricevuta_rapida(df=None, context_key="ricevuta_rapida"):
    """Schermata rapida per Reception: seleziona un pagamento reale e scarica la ricevuta PDF."""
    st.header("🧾 Stampa ricevuta pagamento")
    st.caption("Seleziona un incasso già registrato nello storico pagamenti e genera la ricevuta PDF.")

    pag_df = load_pagamenti()
    if pag_df.empty:
        st.info("Nessun pagamento registrato nello storico. Prima registra un incasso.")
        return

    if df is None or getattr(df, "empty", True):
        df = load_clienti()

    clienti_df = df[["id", "nome", "cognome"]].copy() if not df.empty and {"id", "nome", "cognome"}.issubset(df.columns) else pd.DataFrame(columns=["id", "nome", "cognome"])
    clienti_df["cliente"] = clienti_df["nome"].fillna("") + " " + clienti_df["cognome"].fillna("")

    pag_view = pag_df.merge(clienti_df[["id", "cliente"]], left_on="cliente_id", right_on="id", how="left", suffixes=("", "_cliente"))
    pag_view["cliente"] = pag_view["cliente"].fillna("Cliente ID " + pag_view["cliente_id"].astype(str))
    pag_view = pag_view.sort_values("id", ascending=False).copy()

    c1, c2, c3 = st.columns(3)
    with c1:
        clienti_filter = ["Tutti"] + sorted([x for x in pag_view["cliente"].dropna().unique().tolist() if str(x).strip()])
        filtro_cliente = st.selectbox("Cliente", clienti_filter, key=f"{context_key}_cliente")
    with c2:
        data_da = st.date_input("Da data", value=date(2020, 1, 1), format="DD/MM/YYYY", key=f"{context_key}_data_da")
    with c3:
        data_a = st.date_input("A data", value=date.today(), format="DD/MM/YYYY", key=f"{context_key}_data_a")

    pag_filtrato = pag_view.copy()
    if filtro_cliente != "Tutti":
        pag_filtrato = pag_filtrato[pag_filtrato["cliente"] == filtro_cliente]
    if "data_pagamento" in pag_filtrato.columns:
        pag_filtrato = pag_filtrato[
            (pag_filtrato["data_pagamento"].astype(str) >= str(data_da)) &
            (pag_filtrato["data_pagamento"].astype(str) <= str(data_a))
        ]

    if pag_filtrato.empty:
        st.warning("Nessun pagamento trovato con questi filtri.")
        return

    st.caption(f"Movimenti disponibili: {len(pag_filtrato)}")
    pag_filtrato["label_ricevuta"] = (
        pag_filtrato["id"].astype(str) + " - " +
        pag_filtrato["cliente"].fillna("").astype(str) + " - " +
        pag_filtrato["data_pagamento_it"].fillna("").astype(str) + " - " +
        pag_filtrato["importo"].apply(lambda x: euro(float(x or 0)))
    )
    selected_ricevuta = st.selectbox("Pagamento da stampare", pag_filtrato["label_ricevuta"].tolist(), key=f"{context_key}_select_pagamento")
    pagamento_id_pdf = int(selected_ricevuta.split(" - ")[0])
    pagamento_pdf = get_pagamento_by_id(pagamento_id_pdf)

    if pagamento_pdf:
        st.info("Controlla il pagamento selezionato e scarica la ricevuta PDF.")
        cols = ["id", "cliente", "data_pagamento_it", "importo", "metodo_pagamento", "rata_label", "note"]
        row = pag_filtrato[pag_filtrato["id"].astype(int) == pagamento_id_pdf]
        if not row.empty:
            st.dataframe(row[[c for c in cols if c in row.columns]], use_container_width=True, hide_index=True)
        download_ricevuta_button(int(pagamento_pdf.get("cliente_id")), pagamento_id_pdf, context_key)

def frequenza_pagamento_mesi(tipologia_pagamento):
    t = (tipologia_pagamento or "UNICA SOLUZIONE").upper()
    if "MENSILE" in t:
        return 1
    if "TRIMESTRALE" in t:
        return 3
    if "SEMESTRALE" in t:
        return 6
    return 12


def numero_rate_cliente(cliente):
    durata = durata_abbonamento_mesi(cliente.get("tipologia_abbonamento", "ANNUALE"))
    freq = frequenza_pagamento_mesi(cliente.get("tipologia_pagamento", "UNICA SOLUZIONE"))
    return max(1, int((durata + freq - 1) // freq))


def build_piano_rate(cliente):
    importo = float(cliente.get("importo") or 0)
    n_rate = numero_rate_cliente(cliente)
    freq = frequenza_pagamento_mesi(cliente.get("tipologia_pagamento", "UNICA SOLUZIONE"))
    data_start = parse_date(cliente.get("data_inizio_pacchetto") or cliente.get("data_iscrizione"), date.today())

    rata_base = importo / n_rate if n_rate else importo
    piano = []
    for i in range(1, n_rate + 1):
        scadenza = add_months(data_start, (i - 1) * freq)
        piano.append({
            "rata_num": i,
            "rata_label": f"Rata {i}/{n_rate}",
            "scadenza": scadenza,
            "scadenza_it": scadenza.strftime("%d/%m/%Y"),
            "importo_rata": round(rata_base, 2),
        })
    return piano


def pagamenti_cliente(cliente_id):
    dfp = load_pagamenti()
    if dfp.empty:
        return dfp
    return dfp[dfp["cliente_id"].astype(int) == int(cliente_id)].copy()


def importo_pagato_rata(cliente_id, rata_num):
    dfp = pagamenti_cliente(cliente_id)
    if dfp.empty or "rata_num" not in dfp.columns:
        return 0.0
    sub = dfp[pd.to_numeric(dfp["rata_num"], errors="coerce").fillna(0).astype(int) == int(rata_num)]
    return float(pd.to_numeric(sub["importo"], errors="coerce").fillna(0).sum())



def pagato_allocato_su_rata(cliente, rata):
    """
    Logica corretta:
    l'importo_pagato salvato sul cliente copre le rate in ordine cronologico.
    Così, se in iscrizione il cliente ha già pagato tutto, tutte le rate risultano pagate
    anche se non esiste ancora uno storico pagamento collegato a ogni rata.
    """
    try:
        totale_pagato_cliente = float(cliente.get("importo_pagato") or 0)
    except Exception:
        totale_pagato_cliente = 0.0

    piano = build_piano_rate(cliente)
    paid_remaining = totale_pagato_cliente

    for r in piano:
        quota = float(r.get("importo_rata") or 0)
        allocato = min(max(paid_remaining, 0), quota)

        if int(r.get("rata_num")) == int(rata.get("rata_num")):
            # Se ci sono pagamenti specificamente collegati alla rata e superano l'allocazione,
            # prendo il valore maggiore. In condizioni normali l'allocazione basta.
            try:
                pagato_specifico = importo_pagato_rata(int(cliente.get("id")), int(rata.get("rata_num")))
            except Exception:
                pagato_specifico = 0.0
            return max(allocato, pagato_specifico)

        paid_remaining -= quota

    return 0.0


def stato_rata_cliente(cliente, rata, today=None):
    today = today or date.today()
    pagato = pagato_allocato_su_rata(cliente, rata)
    residuo = max(float(rata["importo_rata"]) - pagato, 0)
    if residuo <= 0.01:
        stato = "PAGATA"
    elif rata["scadenza"] < today:
        stato = "SCADUTA"
    elif rata["scadenza"] == today:
        stato = "IN SCADENZA OGGI"
    else:
        stato = "DA PAGARE"
    return stato, pagato, residuo


def stato_rata(cliente_id, rata, today=None):
    today = today or date.today()
    pagato = importo_pagato_rata(cliente_id, rata["rata_num"])
    residuo = max(float(rata["importo_rata"]) - pagato, 0)
    if residuo <= 0.01:
        stato = "PAGATA"
    elif rata["scadenza"] < today:
        stato = "SCADUTA"
    elif rata["scadenza"] == today:
        stato = "IN SCADENZA OGGI"
    else:
        stato = "DA PAGARE"
    return stato, pagato, residuo



def date_pagamento_rata(cliente, rata):
    """
    Restituisce la/e date pagamento collegate alla rata.
    Se non esiste rata_num nello storico, ma la rata risulta coperta dall'importo_pagato cliente,
    usa una data indicativa:
    - data pagamento del movimento cliente se presente
    - altrimenti data iscrizione / inizio pacchetto
    """
    cliente_id = int(cliente.get("id"))
    rata_num = int(rata.get("rata_num"))

    dfp = pagamenti_cliente(cliente_id)
    date_list = []

    if not dfp.empty:
        if "rata_num" in dfp.columns:
            sub = dfp[pd.to_numeric(dfp["rata_num"], errors="coerce").fillna(0).astype(int) == rata_num].copy()
            if not sub.empty and "data_pagamento" in sub.columns:
                for d in sub["data_pagamento"].dropna().astype(str).unique().tolist():
                    date_list.append(format_date_it(d))

        # fallback: se non ci sono date sulla rata specifica, usa i pagamenti più vecchi
        if not date_list and "data_pagamento" in dfp.columns:
            dfp_sorted = dfp.sort_values("id").copy()
            for d in dfp_sorted["data_pagamento"].dropna().astype(str).unique().tolist():
                date_list.append(format_date_it(d))

    if not date_list:
        fallback = cliente.get("data_inizio_pacchetto") or cliente.get("data_iscrizione") or ""
        if fallback:
            date_list.append(format_date_it(fallback))

    # evita duplicati mantenendo ordine
    clean = []
    for d in date_list:
        if d and d not in clean:
            clean.append(d)

    return ", ".join(clean) if clean else "non disponibile"


