def situazione_rate_cliente(cliente):
    cliente_id = int(cliente.get("id"))
    piano = build_piano_rate(cliente)
    dovuto_oggi = 0.0
    pagato_su_rate = 0.0
    scadute = 0
    aperte = 0

    for rata in piano:
        stato, pagato, residuo = stato_rata_cliente(cliente, rata)
        if rata["scadenza"] <= date.today():
            dovuto_oggi += float(rata["importo_rata"])
        pagato_su_rate += pagato
        if stato == "SCADUTA":
            scadute += 1
        if stato != "PAGATA":
            aperte += 1

    scoperto_oggi = max(dovuto_oggi - pagato_su_rate, 0)
    return {
        "dovuto_oggi": dovuto_oggi,
        "pagato_su_rate": pagato_su_rate,
        "scoperto_oggi": scoperto_oggi,
        "rate_scadute": scadute,
        "rate_aperte": aperte,
        "numero_rate": len(piano),
    }


def load_pagamenti():
    sb = get_supabase()
    try:
        data = sb.table("pagamenti").select("*").order("id", desc=True).range(0, 9999).execute().data
    except Exception:
        data = sb.table("pagamenti").select("*").order("id", desc=True).execute().data
    df = pd.DataFrame(data)
    if df.empty:
        return df

    df["importo"] = pd.to_numeric(df["importo"], errors="coerce").fillna(0)
    if "data_pagamento" in df.columns:
        df["data_pagamento_it"] = df["data_pagamento"].apply(format_date_it)
        df["mese"] = pd.to_datetime(df["data_pagamento"], errors="coerce").dt.to_period("M").astype(str)
    return df



def registra_acconto_iniziale_if_needed(cliente_id, data):
    """
    Registra l'acconto iniziale UNA SOLA VOLTA.
    Evita duplicati se la scheda cliente viene salvata più volte o se Streamlit ricarica.
    """
    try:
        acconto = float(data.get("importo_pagato") or 0)
    except Exception:
        acconto = 0

    if acconto <= 0:
        return

    try:
        data_pag = str(data.get("data_iscrizione") or date.today())
        sb = get_supabase()

        existing = (
            sb.table("pagamenti")
            .select("*")
            .eq("cliente_id", int(cliente_id))
            .eq("data_pagamento", data_pag)
            .eq("importo", float(acconto))
            .eq("metodo_pagamento", "ACCONTO ISCRIZIONE")
            .limit(1)
            .execute()
            .data
        )

        if existing:
            return

        insert_pagamento(
            cliente_id,
            data_pag,
            acconto,
            "ACCONTO ISCRIZIONE",
            "Acconto registrato in fase di iscrizione cliente",
            rata_num=1,
            rata_label="Acconto iscrizione / Rata 1",
        )
    except Exception:
        pass




def somma_pagamenti_cliente(cliente_id):
    try:
        pag = pagamenti_cliente(int(cliente_id))
        if pag.empty:
            return 0.0
        return float(pd.to_numeric(pag["importo"], errors="coerce").fillna(0).sum())
    except Exception:
        return 0.0


def allinea_incassi_mancanti_da_schede():
    """
    Crea righe reali nella tabella pagamenti quando importo_pagato in scheda cliente
    è maggiore della somma dei movimenti già registrati.
    Non modifica importo_pagato: storicizza solo la differenza mancante.
    """
    sb = get_supabase()
    clienti = load_clienti()
    if clienti.empty:
        return {"creati": 0, "saltati": 0, "totale": 0.0}

    creati = 0
    saltati = 0
    totale_creato = 0.0

    for _, c in clienti.iterrows():
        try:
            cid = int(c.get("id"))
            importo_pagato_scheda = float(c.get("importo_pagato") or 0)
            if importo_pagato_scheda <= 0:
                saltati += 1
                continue

            pagamenti_registrati = somma_pagamenti_cliente(cid)
            differenza = round(importo_pagato_scheda - pagamenti_registrati, 2)

            if differenza <= 0.01:
                saltati += 1
                continue

            data_mov = c.get("data_iscrizione") or c.get("data_inizio_pacchetto") or date.today()

            # Evita doppioni della stessa procedura
            existing = (
                sb.table("pagamenti")
                .select("*")
                .eq("cliente_id", cid)
                .eq("metodo_pagamento", "ALLINEAMENTO SCHEDA")
                .eq("importo", float(differenza))
                .limit(1)
                .execute()
                .data
            )
            if existing:
                saltati += 1
                continue

            payload = {
                "cliente_id": cid,
                "data_pagamento": str(data_mov),
                "importo": float(differenza),
                "metodo_pagamento": "ALLINEAMENTO SCHEDA",
                "note": "Movimento creato automaticamente per allineare importo_pagato già presente nella scheda cliente.",
                "registrato_da": user_label(),
                "created_at": now_iso(),
                "rata_label": "Allineamento incasso da scheda",
            }
            sb.table("pagamenti").insert(payload).execute()

            insert_history(
                cid,
                "allineamento incasso",
                euro(pagamenti_registrati),
                euro(importo_pagato_scheda),
                f"Creato movimento reale nello storico pagamenti per differenza: {euro(differenza)}"
            )

            creati += 1
            totale_creato += float(differenza)
        except Exception:
            saltati += 1

    return {"creati": creati, "saltati": saltati, "totale": totale_creato}


def render_allinea_incassi_mancanti():
    st.markdown("### Allinea incassi mancanti")
    st.caption("Usa questa funzione solo se alcuni importi pagati sono presenti nella scheda cliente ma non compaiono nello storico pagamenti.")

    st.warning("La ricevuta deve essere generata solo da un incasso reale presente nella tabella superiore. Questa funzione crea i movimenti mancanti nello storico, senza sommare di nuovo il saldo cliente.")

