def insert_pagamento(cliente_id, data_pagamento, importo, metodo_pagamento, note_pagamento, rata_num=None, rata_label=None):
    cliente = get_cliente(cliente_id)
    if not cliente:
        return False, "Cliente non trovato."

    old_paid = float(cliente.get("importo_pagato") or 0)
    new_paid = old_paid + float(importo)

    sb = get_supabase()

    payload = {
        "cliente_id": int(cliente_id),
        "data_pagamento": str(data_pagamento),
        "importo": float(importo),
        "metodo_pagamento": metodo_pagamento,
        "note": note_pagamento,
        "registrato_da": user_label(),
        "created_at": now_iso(),
    }

    if rata_num is not None:
        payload["rata_num"] = int(rata_num)
    if rata_label is not None:
        payload["rata_label"] = str(rata_label)

    sb.table("pagamenti").insert(payload).execute()

    sb.table("clienti").update({
        "importo_pagato": new_paid,
        "updated_at": now_iso(),
    }).eq("id", int(cliente_id)).execute()

    rate_info = f" - {rata_label}" if rata_label else ""
    insert_history(
        cliente_id,
        "pagamento",
        euro(old_paid),
        euro(new_paid),
        f"Incasso registrato{rate_info}: {euro(importo)} - Metodo: {metodo_pagamento} - Note: {note_pagamento}"
    )
    return True, "Pagamento registrato correttamente."


def delete_pagamento(pagamento_id):
    sb = get_supabase()
    data = sb.table("pagamenti").select("*").eq("id", int(pagamento_id)).limit(1).execute().data
    if not data:
        return False, "Pagamento non trovato."

    pagamento = data[0]
    cliente_id = int(pagamento["cliente_id"])
    importo = float(pagamento.get("importo") or 0)

    cliente = get_cliente(cliente_id)
    old_paid = float(cliente.get("importo_pagato") or 0) if cliente else 0
    new_paid = max(old_paid - importo, 0)

    sb.table("pagamenti").delete().eq("id", int(pagamento_id)).execute()
    sb.table("clienti").update({
        "importo_pagato": new_paid,
        "updated_at": now_iso(),
    }).eq("id", cliente_id).execute()

    insert_history(
        cliente_id,
        "eliminazione pagamento",
        euro(old_paid),
        euro(new_paid),
        f"Pagamento eliminato da admin: {euro(importo)}"
    )
    return True, "Pagamento eliminato e saldo cliente ricalcolato."


