def load_accessi_tornello():
    sb = get_supabase()
    try:
        data = sb.table("accessi_tornello").select("*").order("id", desc=True).execute().data
    except Exception:
        data = []
    df = pd.DataFrame(data)
    if not df.empty:
        if "data_accesso" in df.columns:
            df["data_accesso_it"] = df["data_accesso"].apply(format_date_it)
        if "created_at" in df.columns:
            df["created_at_it"] = df["created_at"].apply(lambda x: pd.to_datetime(x).strftime("%d/%m/%Y %H:%M") if x else "")
    return df


def get_cliente_by_badge_uid(badge_uid):
    if not badge_uid:
        return None
    sb = get_supabase()
    try:
        badge = (
            sb.table("badge_clienti")
            .select("*")
            .eq("badge_uid", str(badge_uid).strip())
            .eq("attivo", True)
            .limit(1)
            .execute()
            .data
        )
    except Exception:
        badge = []
    if not badge:
        return None
    return get_cliente(int(badge[0].get("cliente_id")))


def assegna_badge_cliente(cliente_id, badge_uid, note=""):
    if not badge_uid:
        return False, "Inserisci un codice badge/transponder."

    sb = get_supabase()
    badge_uid = str(badge_uid).strip()

    try:
        existing = sb.table("badge_clienti").select("*").eq("badge_uid", badge_uid).limit(1).execute().data
        if existing and int(existing[0].get("cliente_id")) != int(cliente_id):
            return False, "Questo badge risulta già assegnato a un altro cliente."
    except Exception:
        pass

    try:
        existing_cliente = sb.table("badge_clienti").select("*").eq("cliente_id", int(cliente_id)).eq("badge_uid", badge_uid).limit(1).execute().data
        if existing_cliente:
            sb.table("badge_clienti").update({
                "attivo": True,
                "note": note,
                "updated_at": now_iso(),
                "updated_by": user_label(),
            }).eq("id", int(existing_cliente[0].get("id"))).execute()
        else:
            sb.table("badge_clienti").insert({
                "cliente_id": int(cliente_id),
                "badge_uid": badge_uid,
                "attivo": True,
                "note": note,
                "created_at": now_iso(),
                "updated_at": now_iso(),
                "updated_by": user_label(),
            }).execute()

        insert_history(cliente_id, "badge tornello", "", badge_uid, f"Badge assegnato da {user_label()} - {note}")
        return True, "Badge assegnato correttamente."
    except Exception as e:
        return False, f"Errore assegnazione badge: {e}"


def disattiva_badge(badge_id):
    if not is_admin():
        return False, "Operazione riservata all'amministratore."
    sb = get_supabase()
    try:
        data = sb.table("badge_clienti").select("*").eq("id", int(badge_id)).limit(1).execute().data
        if not data:
            return False, "Badge non trovato."
        badge = data[0]
        sb.table("badge_clienti").update({
            "attivo": False,
            "updated_at": now_iso(),
            "updated_by": user_label(),
        }).eq("id", int(badge_id)).execute()
        insert_history(int(badge.get("cliente_id")), "badge tornello", badge.get("badge_uid", ""), "DISATTIVATO", f"Badge disattivato da {user_label()}")
        return True, "Badge disattivato."
    except Exception as e:
        return False, f"Errore disattivazione badge: {e}"


def registra_accesso_tornello(badge_uid, data_accesso=None, ora_accesso=None, direzione="INGRESSO", tornello="HIKVISION", stato_accesso="REGISTRATO", raw_payload=None):
    """
    Funzione usabile sia dall'app sia dal bridge locale.
    Registra l'accesso senza comandare il tornello.
    """
    data_accesso = data_accesso or str(date.today())
    ora_accesso = ora_accesso or datetime.now().strftime("%H:%M:%S")
    badge_uid = str(badge_uid).strip() if badge_uid else ""

    cliente = get_cliente_by_badge_uid(badge_uid)
    cliente_id = int(cliente.get("id")) if cliente else None

    note = ""
    alert_flags = []

    if cliente:
        alerts = get_cliente_alerts(cliente)
        if alerts:
            alert_flags = list(alerts.keys())
            note = " | ".join([f"{k}: {v[1]}" for k, v in alerts.items()])
    else:
        stato_accesso = "BADGE_NON_ASSOCIATO"
        note = "Badge non associato ad alcun cliente KREO."

    sb = get_supabase()
    try:
        payload = {
            "cliente_id": cliente_id,
            "badge_uid": badge_uid,
            "data_accesso": str(data_accesso),
            "ora_accesso": str(ora_accesso),
            "direzione": direzione,
            "tornello": tornello,
            "stato_accesso": stato_accesso,
            "alert_flags": ",".join(alert_flags),
            "note": note,
            "raw_payload": str(raw_payload)[:2500] if raw_payload is not None else "",
            "created_at": now_iso(),
        }
        sb.table("accessi_tornello").insert(payload).execute()

        if cliente_id:
            insert_history(cliente_id, "accesso tornello", "", f"{format_date_it(data_accesso)} {ora_accesso}", f"{direzione} - {stato_accesso} - {note}")

        return True, "Accesso registrato.", cliente_id
    except Exception as e:
        return False, f"Errore registrazione accesso: {e}", cliente_id



def find_pagamenti_duplicati():
    dfp = load_pagamenti()
    if dfp.empty:
        return pd.DataFrame(), pd.DataFrame()

    work = dfp.copy()
    for col in ["cliente_id", "data_pagamento", "importo", "metodo_pagamento"]:
        if col not in work.columns:
            work[col] = ""

    work["dup_key"] = (
        work["cliente_id"].astype(str) + "|" +
        work["data_pagamento"].astype(str) + "|" +
        pd.to_numeric(work["importo"], errors="coerce").fillna(0).round(2).astype(str) + "|" +
        work["metodo_pagamento"].astype(str)
    )

    counts = work.groupby("dup_key").size().reset_index(name="conteggio")
    dup_keys = counts[counts["conteggio"] > 1]["dup_key"].tolist()

    duplicati = work[work["dup_key"].isin(dup_keys)].sort_values(["dup_key", "id"]).copy()
    summary = counts[counts["conteggio"] > 1].copy()
    return duplicati, summary


def delete_pagamenti_duplicati_keep_first():
    if not is_admin():
        return False, "Operazione riservata all'amministratore."

    duplicati, summary = find_pagamenti_duplicati()
    if duplicati.empty:
        return True, "Nessun duplicato trovato."

    ids_to_delete = []
    for dup_key, group in duplicati.groupby("dup_key"):
        group = group.sort_values("id")
        keep_id = int(group.iloc[0]["id"])
        for _, row in group.iloc[1:].iterrows():
            ids_to_delete.append(int(row["id"]))

    deleted = 0
    errors = []
    for pid in ids_to_delete:
        ok, msg = delete_pagamento(pid)
        if ok:
            deleted += 1
        else:
            errors.append(f"ID {pid}: {msg}")

    if errors:
        return False, f"Eliminati {deleted} duplicati, ma alcuni hanno dato errore: {'; '.join(errors[:3])}"

    return True, f"Pulizia completata. Eliminati {deleted} pagamenti duplicati, lasciando una sola riga per movimento."



def badge_sconosciuti_da_accessi():
    accessi = load_accessi_tornello()
    if accessi.empty or "badge_uid" not in accessi.columns:
        return pd.DataFrame()

    badges = load_badge_clienti()
    known = set()
    if not badges.empty and "badge_uid" in badges.columns:
        known = set(badges[badges.get("attivo", True) == True]["badge_uid"].astype(str).str.strip().tolist())

    df = accessi.copy()
    df["badge_uid"] = df["badge_uid"].fillna("").astype(str).str.strip()
    df = df[df["badge_uid"] != ""]
    df = df[~df["badge_uid"].isin(known)]

    if df.empty:
        return pd.DataFrame()

    agg = (
        df.groupby("badge_uid")
        .agg(
            accessi=("id", "count"),
            primo_accesso=("created_at", "min"),
            ultimo_accesso=("created_at", "max"),
            ultimo_stato=("stato_accesso", "last"),
            ultimo_tornello=("tornello", "last"),
            ultima_nota=("note", "last"),
        )
        .reset_index()
        .sort_values("ultimo_accesso", ascending=False)
    )

    return agg


def associa_badge_sconosciuto_a_cliente(badge_uid, cliente_id, note="Associazione da accessi sconosciuti"):
    ok, msg = assegna_badge_cliente(cliente_id, badge_uid, note)
    if not ok:
        return False, msg

    # Aggiorna retroattivamente gli accessi già presenti con quel badge
    sb = get_supabase()
    try:
        sb.table("accessi_tornello").update({
            "cliente_id": int(cliente_id),
            "stato_accesso": "REGISTRATO_ASSOCIATO",
            "note": f"Accesso associato retroattivamente al cliente ID {cliente_id}",
        }).eq("badge_uid", str(badge_uid)).execute()

        insert_history(
            int(cliente_id),
            "associazione badge accessi",
            "",
            str(badge_uid),
            f"Badge associato e accessi precedenti aggiornati. Note: {note}"
        )

        return True, "Badge associato e accessi precedenti aggiornati."
    except Exception as e:
        return False, f"Badge associato, ma errore aggiornamento accessi precedenti: {e}"


