                    c1.metric("Tipologia abbonamento", cliente_piano.get("tipologia_abbonamento", "ANNUALE"))
                    c2.metric("Tipologia pagamento", cliente_piano.get("tipologia_pagamento", ""))
                    c3.metric("Numero rate", numero_rate_cliente(cliente_piano))

                    render_piano_rate_cliente(cliente_piano)

                    if is_admin():
                        st.markdown("---")
                        st.subheader("Correzione pagamenti rata")
                        pag_cliente = pagamenti_cliente(cliente_piano_id)
